import json, sys

def parse_packages(filename):
    # dotnet package list --format json may output multiple JSON objects; take the last complete one
    with open(filename) as f:
        content = f.read().strip()
    # Try parsing as single JSON first
    try:
        data = json.loads(content)
    except json.JSONDecodeError:
        # Find last '{' ... '}' block
        last = content.rfind('}')
        start = 0
        depth = 0
        for i in range(last, -1, -1):
            if content[i] == '}': depth += 1
            elif content[i] == '{': 
                depth -= 1
                if depth == 0:
                    start = i
                    break
        data = json.loads(content[start:last+1])

    result = {}
    for project in data.get('projects', []):
        pname = project['path'].split('/')[-1]
        pkgs = {}
        for fw in project.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = {'requested': pkg.get('requestedVersion',''), 'resolved': pkg.get('resolvedVersion','')}
        result[pname] = pkgs
    return result

